import { describe, it, expect } from "vitest";
import { statusPhrase } from "../../src/utils/internal/status-text.ts";

describe("statusPhrase", () => {
  it("returns standard phrases", () => {
    expect(statusPhrase(404)).toBe("Not Found");
    expect(statusPhrase(422)).toBe("Unprocessable Content");
    expect(statusPhrase(418)).toBeDefined();
  });

  it("returns undefined for unknown status", () => {
    expect(statusPhrase(599)).toBeUndefined();
  });
});

